template.solver:
def solve(n):
    hi = 10**n - 1
    lo = 10**(n-1)
    for x in range(hi, lo - 1, -1):
        s = str(x)
        if '0' in s:
            continue
        if len(set(s)) != n:
            continue
        ok = True
        for c in s:
            if x % int(c) != 0:
                ok = False
                break
        if ok:
            return x
    return 0
